import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS } from './customers.js';
import { getProduct } from './catalogue.js';
import { roundCents } from './money.js';
import { nextInvoiceNumber } from './numbering.js';

/**
 * Create a new invoice with the given customer, issue date, and line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }> }} params
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Validate customer exists
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;

  // Validate issue date format (YYYY-MM-DD)
  if (!/^\d{4}-\d{2}-\d{2}$/.test(issueDate)) return fail('DATE_INVALID');
  const date = new Date(issueDate + 'T00:00:00Z');
  if (isNaN(date.getTime())) return fail('DATE_INVALID');

  // Validate lines is not empty
  if (!lines || lines.length === 0) return fail('NO_LINES');

  // Validate and enrich each line
  const enrichedLines = [];
  for (const line of lines) {
    const { sku, qty, discountPercent } = line;

    // Validate qty is a positive integer
    if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

    // Determine discount: use line's discountPercent if provided, else use tier discount
    let finalDiscount;
    if ('discountPercent' in line) {
      finalDiscount = discountPercent;
    } else {
      finalDiscount = TIER_DISCOUNTS[customerResult.value.tier];
    }

    // Validate discountPercent
    if (typeof finalDiscount !== 'number' || finalDiscount < 0 || finalDiscount > 100) {
      return fail('DISCOUNT_INVALID');
    }

    // Validate SKU exists and get product details
    const productResult = getProduct(sku);
    if (!productResult.ok) return productResult;

    const { name, unitPrice, vatRate } = productResult.value;
    enrichedLines.push({
      sku,
      name,
      qty,
      unitPrice,
      vatRate,
      discountPercent: finalDiscount,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
  });
}

/**
 * Calculate the total for a single line item: qty × unitPrice.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return roundCents(line.qty * line.unitPrice);
}

/**
 * Calculate totals for an invoice: subtotal (sum of line totals), discount (sum of line discounts), and total.
 * @param {{ lines: Array }} invoice
 * @returns {{ ok: true, value: { subtotal: number, discount: number, total: number } } | { ok: false, error: string }}
 */
export function invoiceTotals(invoice) {
  if (!invoice || !Array.isArray(invoice.lines)) {
    return fail('INVALID_INVOICE');
  }
  let subtotal = 0;
  let discount = 0;
  for (const line of invoice.lines) {
    const lineGrossTotal = lineTotal(line);
    subtotal += lineGrossTotal;
    const discountPercent = line.discountPercent ?? 0;
    const lineDiscount = roundCents(lineGrossTotal * discountPercent / 100);
    discount += lineDiscount;
  }
  const total = Math.max(0, roundCents(subtotal - discount));
  return ok({
    subtotal: Math.max(0, subtotal),
    discount: Math.max(0, discount),
    total,
  });
}

/**
 * Add or increase a line on a draft invoice.
 * @param {{ status: string, lines: Array, customerId: string }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} params
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, params) {
  const { sku, qty, discountPercent } = params;

  // Check status and structure
  if (!invoice || invoice.status !== 'draft' || !Array.isArray(invoice.lines)) {
    return fail('NOT_DRAFT');
  }

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Determine discount: use line's discountPercent if provided, else use tier discount
  let finalDiscount;
  if ('discountPercent' in params) {
    finalDiscount = discountPercent;
  } else {
    const customerResult = getCustomer(invoice.customerId);
    if (!customerResult.ok) return customerResult;
    finalDiscount = TIER_DISCOUNTS[customerResult.value.tier];
  }

  // Validate discountPercent
  if (typeof finalDiscount !== 'number' || finalDiscount < 0 || finalDiscount > 100) {
    return fail('DISCOUNT_INVALID');
  }

  // Validate SKU exists
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const { name, unitPrice, vatRate } = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  // Find existing line with this SKU
  const existingIndex = newLines.findIndex((line) => line.sku === sku);
  if (existingIndex >= 0) {
    // Increase qty on existing line
    newLines[existingIndex] = {
      ...newLines[existingIndex],
      qty: newLines[existingIndex].qty + qty,
    };
  } else {
    // Add new line
    newLines.push({
      sku,
      name,
      qty,
      unitPrice,
      vatRate,
      discountPercent: finalDiscount,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check status and structure
  if (!invoice || invoice.status !== 'draft' || !Array.isArray(invoice.lines)) {
    return fail('NOT_DRAFT');
  }

  // Find line with this SKU
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) {
    return fail('LINE_NOT_FOUND');
  }

  // Check if this is the last line
  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  // Create new invoice without this line
  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing its status to 'issued'.
 * @param {{ status: string, issueDate: string }} invoice
 * @param {Array<string>} existingNumbers - invoice numbers already used
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check invoice is draft
  if (!invoice || invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

