test('invoiceTotals applies VAT to amount after discount', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 10 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 100000);
  assert.equal(r.value.discount, 10000);
  const amountAfterDiscount = 100000 - 10000;
  const vat = Math.round(amountAfterDiscount * 21 / 100);
  assert.equal(r.value.vat, vat);
  assert.equal(r.value.total, 100000 - 10000 + vat);
});

